sql_query:
SELECT "Trial name"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Trial name", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Non-Small Cell Lung' AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Trial name" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Trial name", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Non-Small Cell Lung' AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_trial_acronym(source_value) AS "trial_acronym"
FROM base;
